package prompt

import (
	"errors"
	"math"
	"strconv"
	"strings"
	"unicode"
)

// ComfyUI v0.28.0's prompt grammar, re-implemented from its observed
// behaviour (comfy/sd1_clip.py escape_important → parse_parentheses →
// token_weights → unescape_important). Written fresh — ComfyUI is GPL —
// and pinned by testdata/comfy_parse.json, generated by running the
// pinned Python functions in isolation (eval/comfy_parse_fixtures.py).
//
// compliance parses the EXACT strings patched into CLIPTextEncode with
// this, so the check reads what the encoder reads.

// Segment is one weighted stretch of text as ComfyUI tokenizes it.
type Segment struct {
	Text   string
	Weight float64
}

// ErrComfyAmbiguous: input whose ComfyUI reading this port can't pin
// exactly (non-ASCII digits/space in a weight suffix, recursion past
// Python's limit). Callers fail closed.
var ErrComfyAmbiguous = errors.New("prompt: ComfyUI reading is ambiguous")

const maxComfyDepth = 900 // Python's default recursion limit is 1000

const (
	sentinelClose = "\x00\x01"
	sentinelOpen  = "\x00\x02"
)

// ComfyParse returns the weighted segments ComfyUI would tokenize.
func ComfyParse(s string) ([]Segment, error) {
	esc := strings.ReplaceAll(s, `\)`, sentinelClose)
	esc = strings.ReplaceAll(esc, `\(`, sentinelOpen)
	var out []Segment
	if err := tokenWeights([]rune(esc), 1.0, 0, &out); err != nil {
		return nil, err
	}
	for i := range out {
		t := strings.ReplaceAll(out[i].Text, sentinelClose, ")")
		out[i].Text = strings.ReplaceAll(t, sentinelOpen, "(")
	}
	return out, nil
}

// parseParentheses splits at nesting level 0 into plain stretches and
// "(…)" groups. A stray ")" drives the level negative, after which every
// paren is plain text — ComfyUI's behaviour, reproduced on purpose.
func parseParentheses(rs []rune) [][]rune {
	var result [][]rune
	var cur []rune
	level := 0
	for _, c := range rs {
		switch c {
		case '(':
			if level == 0 {
				if len(cur) > 0 {
					result = append(result, cur)
				}
				cur = []rune{'('}
			} else {
				cur = append(cur, c)
			}
			level++
		case ')':
			level--
			if level == 0 {
				result = append(result, append(cur, ')'))
				cur = nil
			} else {
				cur = append(cur, c)
			}
		default:
			cur = append(cur, c)
		}
	}
	if len(cur) > 0 {
		result = append(result, cur)
	}
	return result
}

func tokenWeights(rs []rune, current float64, depth int, out *[]Segment) error {
	if depth > maxComfyDepth {
		return ErrComfyAmbiguous
	}
	for _, x := range parseParentheses(rs) {
		w := current
		if len(x) >= 2 && x[0] == '(' && x[len(x)-1] == ')' {
			x = x[1 : len(x)-1]
			xx := -1
			for k := len(x) - 1; k >= 0; k-- {
				if x[k] == ':' {
					xx = k
					break
				}
			}
			w *= 1.1
			if xx > 0 {
				f, ok, amb := pyFloat(string(x[xx+1:]))
				if amb {
					return ErrComfyAmbiguous
				}
				if ok {
					w = f
					x = x[:xx]
				}
			}
			if err := tokenWeights(x, w, depth+1, out); err != nil {
				return err
			}
			continue
		}
		*out = append(*out, Segment{Text: string(x), Weight: current})
	}
	return nil
}

// pyFloat reproduces Python's float(str) acceptance: surrounding
// whitespace, a sign, digits with single underscores between them, an
// optional fraction and exponent, or inf/infinity/nan in any case.
// amb is true for non-ASCII digits or spaces, which Python would accept
// and this port refuses to guess at.
func pyFloat(s string) (v float64, ok, amb bool) {
	for _, r := range s {
		if r > 127 && (unicode.IsDigit(r) || unicode.IsSpace(r)) {
			return 0, false, true
		}
	}
	t := strings.TrimFunc(s, func(r rune) bool {
		return r == ' ' || (r >= '\t' && r <= '\r') || (r >= 0x1c && r <= 0x1f)
	})
	if t == "" {
		return 0, false, false
	}
	body := t
	neg := false
	if body[0] == '+' || body[0] == '-' {
		neg = body[0] == '-'
		body = body[1:]
	}
	switch strings.ToLower(body) {
	case "inf", "infinity":
		if neg {
			return math.Inf(-1), true, false
		}
		return math.Inf(1), true, false
	case "nan":
		return math.NaN(), true, false
	}
	i := 0
	digitpart := func() bool {
		start := i
		if i >= len(body) || !isASCIIDigitByte(body[i]) {
			return false
		}
		for i < len(body) {
			switch {
			case isASCIIDigitByte(body[i]):
				i++
			case body[i] == '_' && i+1 < len(body) && isASCIIDigitByte(body[i+1]) && i > start:
				i++
			default:
				return true
			}
		}
		return true
	}
	intPart := digitpart()
	frac := false
	if i < len(body) && body[i] == '.' {
		i++
		frac = digitpart()
	}
	if !intPart && !frac {
		return 0, false, false
	}
	if i < len(body) && (body[i] == 'e' || body[i] == 'E') {
		i++
		if i < len(body) && (body[i] == '+' || body[i] == '-') {
			i++
		}
		if !digitpart() {
			return 0, false, false
		}
	}
	if i != len(body) {
		return 0, false, false
	}
	f, err := strconv.ParseFloat(strings.ReplaceAll(t, "_", ""), 64)
	if err != nil && !isRangeErr(err) {
		return 0, false, false
	}
	return f, true, false
}

func isASCIIDigitByte(b byte) bool { return b >= '0' && b <= '9' }

// plainDecimal accepts only what a person types as a weight: optional
// sign, digits, optional fraction. The SD auto-convert uses it.
func plainDecimal(s string) (float64, error) {
	t := strings.TrimSpace(s)
	body := strings.TrimLeft(t, "+-")
	if len(t)-len(body) > 1 || body == "" || body == "." {
		return 0, strconv.ErrSyntax
	}
	dots := 0
	for _, c := range body {
		switch {
		case c == '.':
			dots++
		case c < '0' || c > '9':
			return 0, strconv.ErrSyntax
		}
	}
	if dots > 1 {
		return 0, strconv.ErrSyntax
	}
	return strconv.ParseFloat(t, 64)
}

// ComfyTags splits ComfyUI segments at commas into tags (whitespace
// trimmed and collapsed like Parse), each run carrying the ComfyUI weight
// as both Weight and Emitted.
func ComfyTags(segs []Segment) []Tag {
	var tags []Tag
	var cur []wrune
	flush := func() {
		a, b := 0, len(cur)
		for a < b && unicode.IsSpace(cur[a].r) {
			a++
		}
		for b > a && unicode.IsSpace(cur[b-1].r) {
			b--
		}
		if a < b {
			tags = append(tags, tagFromRunes(cur[a:b]))
		}
		cur = cur[:0]
	}
	for _, sg := range segs {
		for _, r := range sg.Text {
			if r == ',' {
				flush()
				continue
			}
			cur = append(cur, wrune{r, sg.Weight})
		}
	}
	flush()
	return tags
}

func tagFromRunes(rs []wrune) Tag {
	var t Tag
	var sb, tb strings.Builder
	prevSpace := false
	cur := rs[0].w
	for _, e := range rs {
		r := e.r
		if unicode.IsSpace(r) {
			if prevSpace {
				continue
			}
			prevSpace = true
			r = ' '
		} else {
			prevSpace = false
		}
		if e.w != cur && r != ' ' {
			t.Runs = append(t.Runs, Run{Text: sb.String(), Weight: cur, Emitted: cur})
			sb.Reset()
			cur = e.w
		}
		sb.WriteRune(r)
		tb.WriteRune(r)
	}
	t.Runs = append(t.Runs, Run{Text: sb.String(), Weight: cur, Emitted: cur})
	t.Text = tb.String()
	t.Name = Normalize(t.Text)
	return t
}

// HasEmbedding reports a ComfyUI textual-inversion reference anywhere
// (case-insensitive — stricter than ComfyUI's own word-start check).
func HasEmbedding(s string) bool {
	return strings.Contains(strings.ToLower(s), "embedding:")
}
